let ctrl;
async function ask(prompt) {
  ctrl = new AbortController();
  try {
    const res = await fetch('/api/chat',
    { method: 'POST', body: prompt, signal: ctrl.signal });
    await render(res.body);
  } catch (err) {
    if (err.name !== 'AbortError') throw err;
  }
}
