const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const retryable = (s) => s === 429 || s >= 500;
async function withRetry(call, tries = 3, base = 500) {
  for (let i = 1; ; i++) {
    const res = await call();
    if (res.ok || i >= tries) return res;
    if (!retryable(res.status)) return res;
    const after = Number(res.headers.get('Retry-After'));
    const jitter = Math.random() * base * 2 ** i;
    await sleep(after > 0 ? after * 1000 : jitter);
  }
}

